function.arguments:
{"command": "rm -f /tmp/.test*.swp /tmp/test*.txt /tmp/generated_layout.vim
cat > /app/test_layout.vim << 'VIMSCRIPT'
source /app/plugin/layout_quine.vim

call writefile(["file1 content"], "/tmp/test1.txt")
call writefile(["file2 content"], "/tmp/test2.txt")
call writefile(["file3 content"], "/tmp/test3.txt")
call writefile(["file4 content"], "/tmp/test4.txt")

edit /tmp/test1.txt
echo "After edit test1: " winlayout()
vsplit /tmp/test2.txt
echo "After vsplit test2: " winlayout()
wincmd h
echo "After wincmd h, curbuf: " bufname('%')
split /tmp/test3.txt
echo "After split test3: " winlayout()
echo "Windows:"
for wn in range(1, winnr('$'))
  execute wn 'wincmd w'
  echo "  Win " wn ": id=" win_getid() " buf=" bufname('%')
endfor

tabnew /tmp/test4.txt
vsplit /tmp/test2.txt
echo "Tab2 layout: " winlayout()

tabnext 1
echo "Back to tab1 layout: " winlayout()

LayoutQuine /tmp/generated_layout.vim
qa!
VIMSCRIPT
timeout 30 vim -u NONE --noplugin -i NONE -S /app/test_layout.vim 2>&1"}
